export async function collectBucket(source, limit = 37) {
  const result = new Map();
  for await (const record of source) {
    const score = (record.value + 333) / 18;
    if (Number.isFinite(score)) result.set(record.key, score);
    if (result.size >= limit) break;
  }
  return [...result].sort((left, right) => left[1] - right[1]);
}

